import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BvlN9b-o.js";const h=JSON.parse('{"title":"变量来源与作用域","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/reference/configuration-sources","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"reference/configuration-sources.md","filePath":"reference/configuration-sources.md"}'),c={name:"reference/configuration-sources.md"};function d(b,e,s,f,n,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="变量来源与作用域" tabindex="-1">变量来源与作用域 <a class="header-anchor" href="#变量来源与作用域" aria-label="Permalink to &quot;变量来源与作用域&quot;">​</a></h1><p>配置先按读取者分类。API、Worker 的变量与默认值在 <a href="./config">生成服务端配置</a>；它们来自 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/src/bin/config-reference.rs" target="_blank" rel="noreferrer">Rust 配置导出程序</a>，不在本页重复默认值。添加服务端配置时同时更新所属 <code>FIELDS</code>、实际读取逻辑和 <code>.env.example</code>，文档检查会发现缺少的示例键。</p><h2 id="api-与-worker" tabindex="-1">API 与 Worker <a class="header-anchor" href="#api-与-worker" aria-label="Permalink to &quot;API 与 Worker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量范围</th><th>读取来源</th><th>作用域 / 边界</th></tr></thead><tbody><tr><td>数据库、监听、认证、文件和上传限额</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/config.rs" target="_blank" rel="noreferrer">Settings / AuthSettings / FileLimits</a></td><td>服务端启动验证；生产环境中 APP_ORIGIN 是可信浏览器 origin，不是 API 内部容器地址</td></tr><tr><td>Worker 监听、租约、心跳与停机</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">WorkerPolicy / FIELDS</a></td><td>Worker 进程；API 与 Worker 共用数据库和对象存储设置</td></tr><tr><td>缓存与限流策略</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/cache.rs" target="_blank" rel="noreferrer">Cache</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/rate_limit/mod.rs" target="_blank" rel="noreferrer">RateLimiter</a></td><td>API 启动构造并共享实例；Redis 失联时按策略降级</td></tr><tr><td>SMTP、邮件加密、密码恢复</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/mail.rs" target="_blank" rel="noreferrer">邮件配置</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/identity/password_reset/mod.rs" target="_blank" rel="noreferrer">PasswordReset</a></td><td>API/Worker 必须使用一致密钥版本；生产秘密由部署方提供</td></tr><tr><td>遥测队列、端点与超时</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/telemetry/settings.rs" target="_blank" rel="noreferrer">TelemetrySettings</a></td><td>API/Worker 的有界导出；<code>RUST_LOG</code> 由进程的 EnvFilter 读取</td></tr></tbody></table><p>知识库导出的 <code>EXPORT_*</code> 变量由 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/knowledge/exports/configuration.rs" target="_blank" rel="noreferrer">ExportPolicy</a>读取，属于参考业务。移除该业务时，所有权清单同时移除导出配置；你自己的工单导出应定义自己的策略。</p><h2 id="本地开发与容器" tabindex="-1">本地开发与容器 <a class="header-anchor" href="#本地开发与容器" aria-label="Permalink to &quot;本地开发与容器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>来源</th><th>用途与限制</th></tr></thead><tbody><tr><td><code>POSTGRES_PASSWORD</code>、<code>POSTGRES_PORT</code>、<code>REDIS_PORT</code>、<code>RUSTFS_PORT</code>、<code>MAILPIT_SMTP_PORT</code>、<code>MAILPIT_HTTP_PORT</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/compose.yaml" target="_blank" rel="noreferrer">compose.yaml</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/.env.example" target="_blank" rel="noreferrer">.env.example</a></td><td>开发容器凭据和宿主机端口；不是前端配置</td></tr><tr><td><code>WEB_PORT</code>、<code>VITE_API_PROXY</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/web/vite.config.ts" target="_blank" rel="noreferrer">Web Vite 配置</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/dev.mjs" target="_blank" rel="noreferrer">dev.mjs</a></td><td>本地监听 / 开发服务器代理目标；不会让浏览器读取数据库 URL</td></tr><tr><td><code>TELEMETRY_HTTP_PORT</code>、<code>PROMETHEUS_PORT</code>、<code>LOKI_PORT</code>、<code>TEMPO_PORT</code>、<code>GRAFANA_PORT</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/lib/observability.mjs" target="_blank" rel="noreferrer">可观测性脚本</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/compose.observability.yaml" target="_blank" rel="noreferrer">组合配置</a></td><td>可选本地观测依赖端口</td></tr><tr><td><code>CARGO_BUILD_JOBS</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/lib/process.mjs" target="_blank" rel="noreferrer">开发进程工具</a>、Cargo</td><td>编译并发；影响构建资源，不是业务运行参数</td></tr></tbody></table><p><code>developmentEnv()</code> 使用 Node 的 dotenv parser，合并顺序为 <code>.env.example</code> → 未跟踪的 <code>.env</code> → 进程环境；后者覆盖前者。开发捕获邮件启用且未提供加密 key 时，由 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/lib/development-mail-key.mjs" target="_blank" rel="noreferrer">开发密钥工具</a>创建本机受保护文件，文档构建不读取该文件。直接 <code>cargo run</code> 不会自动套用这套合并，优先使用 task runner。</p><p>在 <code>.env</code> 中只改对应的 <code>*_PORT</code>。开发环境读取器从 <code>POSTGRES_USER</code>、<code>POSTGRES_PASSWORD</code>、<code>POSTGRES_DB</code> 和端口派生 <code>DATABASE_URL</code>；同时派生 Redis/S3 地址、<code>APP_BIND</code>、<code>WORKER_BIND</code>、<code>APP_ORIGIN</code>、<code>VITE_API_PROXY</code>、桌面入口和 SMTP 端口。显式填写这些派生变量仍可连接外部服务；沿用旧 <code>.env</code> 时移除不再需要的显式地址，才能让端口修改自动生效。默认宿主端口采用高位段，容器内部端口保持服务原生值。</p><p><code>just services-up</code> 和 <code>just dev</code> 都先检查宿主监听与 Docker 已发布端口，再启动并核对真实端口映射。<code>compose.yaml</code> 无固定项目名，开发入口按目录名称和完整路径摘要派生容器、卷和网络 namespace。复制已创建的项目后应重新分配 <code>.env</code> 端口；通过脚手架创建的各副本已经分配独立端口。</p><h2 id="浏览器与桌面" tabindex="-1">浏览器与桌面 <a class="header-anchor" href="#浏览器与桌面" aria-label="Permalink to &quot;浏览器与桌面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>来源</th><th>作用域</th></tr></thead><tbody><tr><td><code>VITE_DOCS_URL</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/web/src/main.tsx" target="_blank" rel="noreferrer">文档入口配置</a></td><td>Vite 构建进浏览器的公共文档 URL；只填公开地址</td></tr><tr><td><code>SAAS_DESKTOP_ORIGIN</code>、<code>SAAS_DESKTOP_DOWNLOADS_DIR</code>、<code>SAAS_DESKTOP_USER_DATA_DIR</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/desktop/src/main.ts" target="_blank" rel="noreferrer">Electron main</a></td><td>桌面进程的页面入口、下载与用户数据目录；API 不读取</td></tr></tbody></table><p>Vite 前缀变量可能进入公开 bundle。数据库密码、Session secret、API Key、SMTP 密码和邮件加密 key 不能使用 <code>VITE_</code> 命名或放进客户端源码。</p><h2 id="文档发布与部署" tabindex="-1">文档发布与部署 <a class="header-anchor" href="#文档发布与部署" aria-label="Permalink to &quot;文档发布与部署&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><code>GITHUB_REPOSITORY</code>、<code>DOCS_BASE</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/docs/.vitepress/config.mts" target="_blank" rel="noreferrer">VitePress 配置</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/check-docs-build.mjs" target="_blank" rel="noreferrer">构建链接检查</a></td><td>仓库 URL / 发布子路径；默认路径由仓库名推导</td></tr><tr><td><code>DOCS_SOURCE_REF</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/lib/docs.mjs" target="_blank" rel="noreferrer">文档投影器</a></td><td>源码链接和页脚版本；未设置时取当前 Git HEAD。页脚不代表每个教程命令都运行过</td></tr><tr><td><code>ENV_FILE</code> 与生产域名、端口和数据库凭据</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/deploy/production/env.production.example" target="_blank" rel="noreferrer">生产环境样例</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/compose.production.yaml" target="_blank" rel="noreferrer">生产组合</a></td><td>部署容器、HTTPS 与受保护配置；不由文档构建读取</td></tr></tbody></table><p>查不到变量时，先在读取代码确认其类别，再查看对应样例；不要把开发容器端口或文档发布变量加入 Rust Settings。生产配置的启动验证与 HTTPS 操作见 <a href="./../tutorials/single-machine-production">部署指南</a>。</p><hr><p>源码版本：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/reference/configuration-sources.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',18)])])}const m=a(c,[["render",d]]);export{h as __pageData,m as default};
